function newAbayaProduct():Product{
 const id=`product-${crypto.randomUUID()}`;
 const customizationSteps=customizationDefaults.abaya.map((step,index)=>({id:`${id}-step-${index+1}`,title:step.title,description:'',required:step.title==='Size',available:true,options:step.options.map((option,optionIndex)=>({id:`${id}-step-${index+1}-option-${optionIndex+1}`,name:option.name,priceAdjustment:option.priceAdjustment,available:true,visible:true}))}));
 return{...blankProduct,id,category:'Abaya',name:'',customizationSteps,measurements:[],measurementsEnabled:false};
}
