const isVercelBlobImageUrl=(value:unknown):value is string=>{if(typeof value!=='string')return false;try{const url=new URL(value);return url.protocol==='https:'&&(url.hostname==='blob.vercel-storage.com'||url.hostname.endsWith('.blob.vercel-storage.com'))}catch{return false}};
function AdminModelPhotoPreview({src,name}:{src?:string;name:string}){const [failed,setFailed]=useState(false);useEffect(()=>setFailed(false),[src]);if(!src||failed)return <div className="model-admin-photo-preview model-admin-photo-fallback" role="img" aria-label={`${name||'Model'} photo not uploaded`}><span>Upload this model’s photo</span></div>;return <div className="model-admin-photo-preview"><img src={productImageSource(src)} alt={`${name} primary model photo`} onError={()=>setFailed(true)}/><span>Primary photo</span></div>}
const uploadStageLabel:Record<UploadFailureStage,string>={authentication:'Admin authentication',token:'Secure upload authorization',blob:'Vercel Blob transfer',confirmation:'Vercel Blob confirmation',save:'Saving the image to this product'};
const imageUploadErrorMessage=(error:unknown)=>{
 if(error instanceof ImageUploadError){
  const file=error.fileName?`“${error.fileName}”: `:'';
  const status=error.statusCode?` (HTTP ${error.statusCode})`:'';
  return `${file}${uploadStageLabel[error.stage]} failed${status}. ${error.message} Previously saved images in this batch were kept.`;
 }
 if(error instanceof Error&&/use a jpeg, png, webp, or gif image|selected image is empty|exceeds vercel blob/i.test(error.message))return error.message;
 return 'Image upload failed. The current image was not marked complete; any earlier images saved in this batch were kept. Retry or contact the atelier administrator.';
};
type PhotoSaveTarget={resource:'productPhotos'|'optionPhotos';productId:string;stepId?:string;optionId?:string;modelId?:string;modelStepId?:string;category?:'colors'|'fabrics'|'stitching';action:'add'|'replace';index?:number};
type PendingPhotoSave={target:PhotoSaveTarget;url:string;fileName:string;remainingFiles:File[]};
function applySavedPhotos(product:Product,target:PhotoSaveTarget,images:string[]):Product{
 if(target.resource==='productPhotos')return{...product,images,image:images[0]||''};
 const update=(option:CustomizationOption)=>({...option,images,image:images[0]||''});
 if(target.modelId)return{...product,customizationSteps:(product.customizationSteps||[]).map(step=>({...step,options:step.options.map(model=>{if(model.id!==target.modelId)return model;const configuration={...model.modelCustomization};if(target.category)configuration[target.category]={...configuration[target.category],options:(configuration[target.category]?.options||[]).map(option=>option.id===target.optionId?update(option):option)};if(target.modelStepId)configuration.steps=(configuration.steps||[]).map(customStep=>customStep.id===target.modelStepId?{...customStep,options:customStep.options.map(option=>option.id===target.optionId?update(option):option)}:customStep);return{...model,modelCustomization:configuration}})}))};
 return{...product,customizationSteps:(product.customizationSteps||[]).map(step=>step.id!==target.stepId?step:{...step,options:step.options.map(option=>option.id===target.optionId?update(option):option)})};
}
async function saveUploadedPhoto(target:PhotoSaveTarget,url:string):Promise<string[]>{
 try{return await serializeAdminStoreWrite(()=>withAbortableDeadline(async(signal)=>{
  const response=await fetch('/api/store-data',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({...target,url}),signal});
  let result:{ok?:boolean;productId?:string;images?:unknown}|null=null;
  try{result=await response.json()}catch(error){if(signal.aborted)throw error;result=null}
  if(!response.ok||result?.ok!==true||result?.productId!==target.productId||!Array.isArray(result?.images)||!result.images.includes(url)){
   const statusCode=response.status||undefined;
   const stage:UploadFailureStage=statusCode===401||statusCode===403?'authentication':'save';
   let message='The uploaded image URL was not confirmed in the saved product data.';
   if(statusCode===404||statusCode===409)message='The product or option changed while uploading. Refresh the Admin editor and retry.';
   else if(statusCode===503)message='Store storage is unavailable in this deployment. The photo was not added to the gallery.';
   else if(statusCode&&statusCode>=500)message='The store could not persist the image URL. Refresh to check whether the save completed before retrying.';
   else if(stage==='authentication')message='Your admin session expired before the image could be saved. Sign in again, then refresh the product before retrying.';
   throw new ImageUploadError(stage,message,{statusCode});
  }
  return result.images as string[];
 },{timeoutMs:IMAGE_SAVE_TIMEOUT_MS,onTimeout:()=>new ImageUploadError('save','The store did not confirm the saved image URL before the deadline. Refresh the product to check whether the save completed before retrying.')}) )}
 catch(error){if(error instanceof ImageUploadError)throw error;if(error instanceof TypeError)throw new ImageUploadError('save','The connection to the store save API was interrupted. The gallery was not marked complete; refresh before retrying.',{cause:error});throw new ImageUploadError('save','The uploaded image URL could not be confirmed in the saved product data.',{cause:error})}
}
function seedModelCustomization(product:Product,model:CustomizationOption):ModelCustomization{
 const prior=model.modelCustomization||{};const steps=product.customizationSteps||[];
 const defaults={colors:steps.find(step=>/colou?r/i.test(step.title)),fabrics:steps.find(step=>/fabric|cloth/i.test(step.title)),stitching:steps.find(step=>/stitch/i.test(step.title))};
 const make=(key:ModelCategoryKey):ManagedModelCategory=>{
  const configured=prior[key];if(configured)return configured;
  const source=defaults[key];return{visible:Boolean(source&&source.available!==false),required:source?.required===true,options:(source?.options||[]).map(option=>({...option,id:`option-${crypto.randomUUID()}`,images:[...(option.images||[])],image:option.image||''}))};
 };
 const modelStep=steps.find(step=>/model/i.test(step.title));
 const extraSteps=prior.steps??steps.filter(step=>step.id!==modelStep?.id&&!/colou?r|fabric|cloth|stitch/i.test(step.title)).map(step=>({id:step.id,title:step.title,description:step.description,visible:step.available!==false,required:step.required===true,options:step.options.map(option=>({...option,id:`option-${crypto.randomUUID()}`,images:[...(option.images||[])],image:option.image||''}))}));
 return{colors:make('colors'),fabrics:make('fabrics'),stitching:make('stitching'),steps:extraSteps};
}
function updateModelInProduct(product:Product,modelId:string,update:(model:CustomizationOption)=>CustomizationOption):Product{
 return{...product,customizationSteps:(product.customizationSteps||[]).map(step=>({ ...step, options:step.options.map(model=>model.id===modelId?update(model):model) }))};
}
