  if(ready.some(row=>existing.has(row.prefix))){setImportErrors(['A staged PIN/prefix duplicates a saved rule. Remove or correct that row before adding it.']);return}
  const imported:DeliveryRule[]=ready.map(row=>({id:row.id,area:row.area.trim(),prefix:row.prefix,fee:row.fee!,enabled:false,pinSource:row.pinSource.trim(),feeSource:row.feeSource.trim(),imported:true}));
