 const visibleOrders=useMemo(()=>orders.filter(o=>(statusFilter==='All'||(active==='Payments'?o.statusPayment:o.status)===statusFilter)&&`${o.id} ${o.customer} ${o.product} ${o.delivery?.email||''} ${o.delivery?.phone||''}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sort==='oldest'?a.id.localeCompare(b.id):sort==='amount'?b.total-a.total:b.id.localeCompare(a.id)),[orders,statusFilter,search,sort,active]);
