   const productId=await persistMeasurementGuides(productEditor.measurementGuides||[],null);
   if(!productId)throw new Error('Save the guide details before uploading its photo.');
   const extension=measurementGuideExtensionForMimeType(file.type);
   const pathname=measurementGuideImagePath(productId,guideId,`${crypto.randomUUID()}.${extension}`);
