 const confirmDeliveryStatus=async()=>{if(!deliveryConfirmation||deliverySavingId)return;const {order,delivered}=deliveryConfirmation;setDeliverySavingId(order.id);setDeliveryError('');try{const response=await serializeAdminStoreWrite(()=>requestAdminStoreData<{ok?:boolean;order?:Order}>({method:'PUT',body:{resource:'order',action:'setDeliveryStatus',id:order.id,delivered},timeoutMs:ADMIN_STORE_REQUEST_TIMEOUT_MS,validate:value=>value.ok===true&&value.order?.id===order.id&&value.order.status===(delivered?'Delivered':'Ready to ship')}));if(!response.order)throw new Error('The server did not return the updated order.');setOrders(current=>current.map(item=>item.id===order.id?response.order!:item));setOrderEditor(current=>current?.id===order.id?{...current,...response.order!}:current);setDeliveryConfirmation(null);notify(delivered?'Order marked delivered.':'Delivery status corrected.')}catch(error){setDeliveryError(error instanceof Error?error.message:'Could not update delivery status. The order remains unchanged.')}finally{setDeliverySavingId(null)}};
 const saveOrder=async()=>{if(!orderEditor)return;const {id,customer,total,status,delivery,statusPayment}=orderEditor;const updates=orderEditor.orderType==='custom_reference_photo'?{customer,status,delivery,finalPrice:orderEditor.finalPriceConfirmed?Number(orderEditor.finalPrice):undefined,finalPriceConfirmed:orderEditor.finalPriceConfirmed===true,...(active==='Payments'?{statusPayment}:{})}:{customer,total,status,delivery,...(active==='Payments'?{statusPayment}:{})};if(await mutate({resource:'order',action:'update',id,updates}))setOrderEditor(null)};
 const retryWhatsApp=async(channel:'customer'|'owner')=>{if(!orderEditor||busy)return;setBusy(true);try{const d=await serializeAdminStoreWrite(()=>requestAdminStoreData<{ok?:boolean;order?:Order}>({method:'PUT',body:{resource:'order',action:'retryWhatsApp',id:orderEditor.id,channel},timeoutMs:ADMIN_STORE_REQUEST_TIMEOUT_MS,validate:value=>value.ok===true&&value.order?.id===orderEditor.id}));if(!d.order)throw new Error('The store did not confirm the notification status.');setOrders(current=>current.map(order=>order.id===d.order!.id?d.order!:order));setOrderEditor(current=>current?.id===d.order!.id?{...current,...d.order!}:current);notify(`WhatsApp notification status: ${d.order.whatsappNotifications?.[channel]?.status||'unknown'}.`)}catch(error){notify(error instanceof Error?error.message:'Could not retry the WhatsApp notification. Refresh the order status before trying again.')}finally{setBusy(false)}};
 const remove=async()=>{if(!confirmDelete)return;const {type,id}=confirmDelete;if(type==='product'){const next=products.filter(p=>p.id!==id);if(await mutate({resource:'products',products:next})){setConfirmDelete(null);setConfirmation('')}}else if(await mutate({resource:type,id,action:'delete',confirmation})){setConfirmDelete(null);setConfirmation('')}};
 const saveFlatDeliveryFee=async()=>{if(!isValidFlatDeliveryFee(settings.flatDeliveryFee)){const message='Enter a valid flat delivery fee from ₹0 to ₹10,00,000 (up to two decimal places).';setFlatDeliveryFeeStatus({type:'error',message});notify(message);return}setFlatDeliveryFeeStatus({type:'info',message:'Saving fee to store…'});await mutate({resource:'settings',action:'setFlatDeliveryFee',flatDeliveryFee:settings.flatDeliveryFee})};
 const saveDeliveryRestrictionMode=async()=>{setDeliveryRestrictionStatus({type:'info',message:'Saving destination restriction setting…'});await mutate({resource:'settings',action:'setDeliveryRestrictionMode',restrictDeliveryToConfiguredRules:settings.restrictDeliveryToConfiguredRules})};
  const saveSettings=async()=>{const rules=settings.deliveryRules||[];if(!isValidFlatDeliveryFee(settings.flatDeliveryFee)){notify("Set a valid flat delivery fee from ₹0 to ₹10,00,000 (up to 2 decimal places).");return}if(rules.some(rule=>!/^\d{3,6}$/.test(rule.prefix)||!Number.isFinite(rule.fee)||rule.fee<0)){notify('Each delivery rule needs a 3–6 digit PIN prefix and a valid non-negative fee. Use ₹0 for free delivery.');return}if(new Set(rules.map(rule=>rule.prefix)).size!==rules.length){notify('Each delivery PIN prefix must be unique.');return}await mutate({resource:'settings',settings})};
 const exportCsv=()=>{const rows=active==='Customers'?eligibleCustomers.map(c=>[c.name,c.phone,[c.address,c.city,c.postal].filter(Boolean).join(', '),c.orderId,c.product,c.amountPaid,c.paymentDate,c.deliveryStatus]):orders.map(o=>[o.id,o.customer,o.product,o.date,o.total,o.status,o.statusPayment,o.paymentMethod]);const header=active==='Customers'?['Customer','Phone','Address','Order ID','Product','Amount paid','Payment date','Delivery status']:['ID','Customer','Product','Date','Total','Order status','Payment status','Method'];const csv=[header,...rows].map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`arabian-tailors-${active.toLowerCase()}.csv`;a.click();URL.revokeObjectURL(a.href)};
