   <div className="custom-option-image-tools"><label className="inline-toggle"><input type="checkbox" checked={field.photoPublished===true} disabled={!field.photo||imageUploading||measurementGuideSaving} onChange={event=>void setMeasurementFieldPhotoPublished(field.id,event.target.checked)}/> Published to customers</label>{field.photo&&<button type="button" className="admin-btn secondary" disabled={imageUploading||measurementGuideSaving} onClick={()=>void removeMeasurementFieldPhoto(field.id)}>Remove Photo</button>}</div>
