   <div className="measurement-guide-video-preview">{video.url&&<figure><video src={productImageSource(video.url)} controls playsInline preload="metadata" aria-label="Saved Kandura measurement guide video"/><figcaption>Saved guide video</figcaption></figure>}{pending&&<figure className="measurement-guide-photo-pending"><video src={productImageSource(pending.url)} controls playsInline preload="metadata" aria-label="New Kandura measurement guide video pending save"/><figcaption>{pending.fileName} · URL save pending</figcaption><button type="button" className="admin-btn secondary" disabled={measurementGuideSaving||imageUploading} onClick={()=>void retryMeasurementVideoSave()}>Retry saving video</button></figure>}{!video.url&&!pending&&<p className="measurement-guide-photo-empty">No guide video uploaded</p>}</div>
