 {pendingPhotoSave&&<div className="product-image-error" role="alert"><p>Blob storage confirmed “{pendingPhotoSave.fileName}”, but its URL has not been confirmed in store data. Retry the save below; the photo will not be uploaded again.</p><button type="button" className="admin-btn secondary" disabled={retryingPhotoSave||imageUploading} onClick={()=>void retryPendingPhotoSave()}>{retryingPhotoSave?'Retrying store save…':'Retry saving uploaded photo'}</button></div>}
